"""Settings entry points and exact saved YAML bytes; no YAML is generated by R10."""
import json
import sys
from backend.routers import ipv6_fakeip, ipv6_routes
print(json.dumps([{'fake': ipv6_fakeip.settings(config), 'routes': ipv6_routes.settings(config),
                   'yaml_hex': config.get('mihomo', {}).get('custom_config', '').encode().hex()}
                  for config in json.load(sys.stdin)], ensure_ascii=False))
